import logging
import uuid
from typing import Any, cast
from urllib.parse import urlparse

from django.contrib import messages
from django.contrib.auth.decorators import login_required
from django.contrib.auth.models import User
from django.core.exceptions import ValidationError
from django.core.validators import URLValidator
from django.db import transaction
from django.forms import modelformset_factory  # Import formset factory
from django.http import HttpRequest, HttpResponse, JsonResponse
from django.shortcuts import get_object_or_404, redirect, render
from django.utils import timezone
from django.utils.http import url_has_allowed_host_and_scheme
from django.views.decorators.http import require_POST

from calendars.models import (
    ICAL_URL_MAX_LENGTH,
    CalendarVisibility,
    DeletedExternalEvent,
    ExternalAccountVisibility,  # Added import
    ExternalCalendarAccount,
    ModifiedExternalEvent,
    SyncLog,
)
from events.models import Event
from users.models import FamilyMembership

from ..forms import (
    ExternalAccountVisibilityRuleForm,  # Ensuring correct form name is imported
)
from ..utils.ics_metadata import fetch_ics_metadata, normalize_and_validate_ics_url

logger = logging.getLogger(__name__)

# Import at module level to avoid repeated imports
try:
    from calendars.tasks import sync_calendar as _sync_calendar

    sync_external_calendar: Any = _sync_calendar
except ImportError:
    sync_external_calendar = None
    logger.warning("sync_external_calendar task not available")


def _get_google_provider(request: HttpRequest) -> Any:
    """
    Attempt to fetch the Google provider from django-allauth's registry.
    Returns None if allauth isn't installed or the provider is unavailable.
    """
    try:
        from allauth.socialaccount.providers import registry
    except ImportError:
        logger.info(
            "django-allauth not installed; Google connect URL unavailable for external accounts"
        )
        return None

    try:
        return registry.by_id("google", request)
    except Exception as exc:  # pragma: no cover - defensive logging path
        logger.warning("Unable to load Google provider for external accounts: %s", exc)
        return None


def _get_google_connect_url(request: HttpRequest) -> str | None:
    """
    Build the connect URL for Google accounts using django-allauth.
    Returns None when the provider or integration isn't available.
    """
    provider = _get_google_provider(request)
    if not provider:
        return None

    try:
        url: str = provider.get_login_url(request, process="connect")
        return url
    except Exception as exc:  # pragma: no cover - defensive logging path
        logger.warning("Failed to build Google connect URL: %s", exc)
        return None


@login_required
def external_calendar_list(request: HttpRequest) -> HttpResponse:
    """
    List and manage external calendar connections
    """
    user = cast(User, request.user)  # login_required guarantees User
    calendars = ExternalCalendarAccount.objects.filter(user=user)

    context = {
        "calendars": calendars,
    }

    return render(request, "calendars/external_list.html", context)


@login_required
def external_calendar_connect(request: HttpRequest) -> HttpResponse:
    """
    Connect to an external calendar service
    """
    if request.method == "POST":
        provider = request.POST.get("provider")

        if provider == "GOOGLE":
            # In a real implementation, this would redirect to Google OAuth
            # For now, we'll just show a form to enter the details manually
            return render(request, "calendars/connect_google.html")

        elif provider == "APPLE":
            # For Apple Calendar, we'll show a form to enter the iCal URL
            return render(request, "calendars/connect_apple.html")

        else:
            messages.error(request, "Invalid calendar provider")
            return redirect("calendars:external_calendar_list")

    return render(request, "calendars/connect.html")


@login_required
def quick_calendar_connect(request: HttpRequest) -> HttpResponse:
    """
    Quick and simplified calendar connection for common providers
    """
    user = cast(User, request.user)  # login_required guarantees User
    if request.method == "POST":
        provider = request.POST.get("provider")
        calendar_url = request.POST.get("calendar_url", "").strip()
        calendar_name = request.POST.get("calendar_name", "").strip()

        # Validate and normalize calendar_type
        calendar_type = (
            request.POST.get("calendar_type", "GENERAL") or "GENERAL"
        ).upper()
        allowed_types = {"GENERAL", "SPORTS", "VACATION", "CHARTER"}
        if calendar_type not in allowed_types:
            calendar_type = "GENERAL"

        # Validate sports_subcategory only if type is SPORTS
        sports_subcategory_input = request.POST.get("sports_subcategory", "")
        sports_subcategory: str | None = None
        if calendar_type == "SPORTS" and sports_subcategory_input:
            allowed_sports = {
                "SOCCER",
                "BASKETBALL",
                "ROWING",
                "BALLET",
                "BASEBALL",
                "HOCKEY",
                "OTHER",
            }
            sports_subcategory = (
                sports_subcategory_input.upper()
                if sports_subcategory_input.upper() in allowed_sports
                else None
            )

        # Validate provider against allowlist
        allowed_providers = {"GOOGLE", "URL"}
        if provider not in allowed_providers:
            messages.error(request, "Invalid provider selected.")
            return redirect("calendars:quick_connect")

        if provider == "GOOGLE":
            # Redirect to Google OAuth flow
            return redirect("calendars:external_calendar_connect")

        elif provider == "URL" and calendar_url:
            # Handle direct calendar URL (iCal, WebCal, etc.)
            try:
                # Normalize and validate URL
                url = calendar_url.strip()

                # Convert webcal:// to https://
                if url.lower().startswith("webcal://"):
                    url = "https://" + url[9:]

                # Validate URL scheme
                allowed_schemes = {"http", "https"}
                parsed_url = urlparse(url)

                if not parsed_url.scheme:
                    messages.error(
                        request,
                        "Please provide a complete URL including http:// or https://",
                    )
                    return redirect("calendars:quick_connect")

                if parsed_url.scheme not in allowed_schemes:
                    messages.error(
                        request,
                        "Calendar URL must use http, https, or webcal protocol.",
                    )
                    return redirect("calendars:quick_connect")

                # Validate URL length against model max_length so we surface a
                # friendly message instead of a DB DataError on save.
                if len(url) > ICAL_URL_MAX_LENGTH:
                    messages.error(
                        request,
                        f"Calendar URL is too long (maximum {ICAL_URL_MAX_LENGTH} characters).",
                    )
                    return redirect("calendars:quick_connect")

                # Validate URL format
                url_validator = URLValidator(schemes=list(allowed_schemes))
                try:
                    url_validator(url)
                except ValidationError:
                    messages.error(request, "Please provide a valid calendar URL.")
                    return redirect("calendars:quick_connect")

                safe_url = normalize_and_validate_ics_url(url)
                if safe_url is None:
                    messages.error(
                        request,
                        "Calendar URL points to a private or restricted host.",
                    )
                    return redirect("calendars:quick_connect")
                url = safe_url
                parsed_url = urlparse(url)

                # Auto-detect the provider from URL domain
                domain = parsed_url.netloc.lower()
                if "google.com" in domain or "googleapis.com" in domain:
                    detected_provider = "GOOGLE"
                elif (
                    "outlook" in domain
                    or "office365" in domain
                    or "microsoft.com" in domain
                ):
                    detected_provider = "OUTLOOK"
                elif "icloud.com" in domain or "apple.com" in domain:
                    detected_provider = "APPLE"
                else:
                    detected_provider = "OTHER"

                # If no name provided, try to fetch metadata for a better default
                if not calendar_name:
                    try:
                        metadata = fetch_ics_metadata(url, timeout=3)  # Quick timeout
                        if metadata:
                            # Use the first suggestion or calendar name from metadata
                            if metadata.get("suggested_names"):
                                calendar_name = metadata["suggested_names"][0]
                            elif metadata.get("calendar_name"):
                                calendar_name = metadata["calendar_name"]
                    except Exception as e:
                        logger.debug(
                            f"Could not fetch metadata for name suggestion: {e}"
                        )

                # Create the external calendar account
                # Generate deterministic provider_uid from normalized URL and user to prevent duplicates
                canonical = url.strip().lower()
                uid_source = f"{user.id}:{canonical}"
                stable_hash = uuid.uuid5(uuid.NAMESPACE_URL, uid_source)

                calendar = ExternalCalendarAccount.objects.create(
                    user=user,
                    provider=detected_provider,
                    provider_uid=f"url_{stable_hash}",  # Deterministic ID based on URL and user
                    account_email="",  # Leave empty since we don't have a real email for URL-based calendars
                    account_name=calendar_name or "Quick Calendar",
                    ical_url=url,  # Use normalized URL
                    type=calendar_type,
                    sports_subcategory=sports_subcategory,  # Already validated above
                    is_active=True,
                    sync_enabled=True,
                )

                messages.success(
                    request,
                    f"Calendar '{calendar.account_name}' connected successfully! "
                    "Events will sync shortly.",
                )

                # Trigger initial sync if available
                if sync_external_calendar:
                    sync_external_calendar.delay(calendar.id)
                else:
                    logger.warning(
                        f"Sync task not available for calendar {calendar.id}"
                    )

                return redirect("calendars:calendar_list")

            except Exception as e:
                logger.error(f"Error creating quick calendar connection: {str(e)}")
                messages.error(
                    request,
                    "Failed to connect calendar. Please check the URL and try again.",
                )
                return redirect("calendars:quick_connect")

        elif provider == "URL" and not calendar_url:
            messages.error(request, "Please provide a calendar URL.")
            return redirect("calendars:quick_connect")
        else:
            messages.error(
                request, "Invalid request. Please select a provider or provide a URL."
            )
            return redirect("calendars:quick_connect")

    # GET request - show the quick connect form
    context = {
        "title": "Add External Calendar",
        "description": "Connect calendars from Google, sports teams, schools, or any source with an iCal URL",
    }
    return render(request, "calendars/quick_connect.html", context)


@login_required
def external_calendar_detail(request: HttpRequest, calendar_id: str) -> HttpResponse:
    """
    View and manage a specific external calendar
    """
    user = cast(User, request.user)  # login_required guarantees User
    calendar = get_object_or_404(ExternalCalendarAccount, id=calendar_id, user=user)

    if request.method == "POST":
        action = request.POST.get("action")

        if action == "sync":
            # Check if calendar is active and sync is enabled
            if not calendar.is_active or not calendar.sync_enabled:
                messages.error(
                    request,
                    f'Calendar "{calendar.account_name}" is not active or sync is disabled.',
                )
            else:
                try:
                    # Trigger the sync task
                    # Use the module-level import if available, otherwise import locally
                    if sync_external_calendar:
                        sync_external_calendar.delay(calendar.id)
                        messages.success(
                            request,
                            f'Sync for calendar "{calendar.account_name}" has been scheduled.',
                        )
                    else:
                        logger.warning("sync_external_calendar task not available")
                        messages.warning(
                            request,
                            "Sync task is not available. Please try again later.",
                        )

                except Exception as e:
                    logger.error(
                        f"Failed to schedule sync for calendar {calendar.id}: {str(e)}"
                    )
                    messages.info(
                        request,
                        "Sync will be processed in the background. Check sync logs later for results.",
                    )

            return redirect(
                "calendars:external_calendar_detail", calendar_id=calendar.id
            )

        # Handle standard form submission (update settings)
        is_active = request.POST.get("is_active") == "on"
        sync_enabled = request.POST.get("sync_enabled") == "on"

        # Get calendar type and sports subcategory
        calendar_type = request.POST.get("type", calendar.type)
        sports_subcategory = request.POST.get(
            "sports_subcategory", calendar.sports_subcategory
        )

        # Get visibility settings
        # Default to existing values or sensible defaults if not in POST (though these likely come from a form)
        # For checkboxes (is_active, sync_enabled), absence usually means False, handled above.

        try:
            current_visibility = calendar.visibility
        except CalendarVisibility.DoesNotExist:
            current_visibility = None

        default_visibility = request.POST.get(
            "default_visibility",
            current_visibility.default_visibility if current_visibility else "ALL",
        )
        visible_to_parents = request.POST.get(
            "visible_to_parents",
            current_visibility.visible_to_parents if current_visibility else "ALL",
        )
        visible_to_grandparents = request.POST.get(
            "visible_to_grandparents",
            current_visibility.visible_to_grandparents if current_visibility else "ALL",
        )
        visible_to_children = request.POST.get(
            "visible_to_children",
            current_visibility.visible_to_children if current_visibility else "BUSY",
        )

        # Get associated users and children
        associated_user_ids = request.POST.getlist("associated_users")
        associated_children = request.POST.getlist("associated_children")

        # Update calendar settings
        calendar.is_active = is_active
        calendar.sync_enabled = sync_enabled
        calendar.type = calendar_type

        # Only set sports_subcategory if type is SPORTS
        if calendar_type == "SPORTS":
            calendar.sports_subcategory = sports_subcategory
        else:
            calendar.sports_subcategory = None

        calendar.save()

        # Update visibility settings
        try:
            visibility = calendar.visibility
        except CalendarVisibility.DoesNotExist:
            visibility = CalendarVisibility(calendar=calendar)

        visibility.default_visibility = default_visibility
        visibility.visible_to_parents = visible_to_parents
        visibility.visible_to_grandparents = visible_to_grandparents
        visibility.visible_to_children = visible_to_children
        visibility.save()

        # Update associated users and children
        calendar.associated_users.clear()
        calendar.associated_children.clear()

        # Process regular users
        if associated_user_ids:
            # Get family memberships for the current user to ensure they can only
            # associate users from their families
            user_families = user.family_memberships.values_list("family_id", flat=True)
            family_members = FamilyMembership.objects.filter(
                family_id__in=user_families
            ).values_list("user_id", flat=True)

            # Filter user_ids to only include family members
            valid_user_ids = [
                int(uid)
                for uid in associated_user_ids
                if int(uid) in family_members or int(uid) == user.id
            ]

            # Add the associated users
            if valid_user_ids:
                users = User.objects.filter(id__in=valid_user_ids)
                calendar.associated_users.add(*users)

        # Process associated children
        if associated_children:
            from users.models import Child

            associated_children_int = [
                int(child_id) for child_id in associated_children
            ]
            children = Child.objects.filter(id__in=associated_children_int)
            calendar.associated_children.add(*children)
            # If child already has a real user_account, also add to associated_users
            for child in children:
                if child.user_account:
                    calendar.associated_users.add(child.user_account)

        messages.success(
            request, f'Calendar "{calendar.account_name}" updated successfully.'
        )
        return redirect("calendars:external_calendar_detail", calendar_id=calendar.id)

    # Get visibility settings
    try:
        visibility = calendar.visibility
    except CalendarVisibility.DoesNotExist:
        # Create default visibility settings if they don't exist
        visibility = CalendarVisibility.objects.create(calendar=calendar)

    # Get sync logs
    sync_logs = SyncLog.objects.filter(calendar=calendar).order_by("-started_at")[:10]

    # Get family members for the associated users selection
    user_families = user.family_memberships.values_list("family_id", flat=True)
    associated_family_members = User.objects.filter(
        family_memberships__family_id__in=user_families
    ).distinct()

    # Get associated children IDs
    from users.models import Child

    associated_children_ids = [
        str(child.id) for child in calendar.associated_children.all()
    ]

    context = {
        "calendar": calendar,
        "visibility": visibility,
        "sync_logs": sync_logs,
        "family_members": associated_family_members,
        "associated_children_ids": associated_children_ids,
    }

    return render(request, "calendars/external_detail.html", context)


@login_required
def external_calendar_delete(request: HttpRequest, calendar_id: str) -> HttpResponse:
    """
    Delete an external calendar and all its associated events
    """
    user = cast(User, request.user)  # login_required guarantees User
    logger.info(
        f"external_calendar_delete called: method={request.method}, calendar_id={calendar_id}, user={user.username}"
    )

    calendar = get_object_or_404(ExternalCalendarAccount, id=calendar_id, user=user)

    logger.info(f"Found calendar: {calendar.account_name} (id={calendar.id})")

    if request.method == "POST":
        logger.info("Processing POST request to delete calendar")
        account_name = calendar.account_name

        try:
            # Use a transaction to ensure all related data is deleted properly
            with transaction.atomic():
                # Get all events associated with this calendar
                # Use calendar_id field which stores the ExternalCalendarAccount.id
                events = Event.objects.filter(
                    is_external=True,
                    calendar_id=str(calendar.id),
                    external_source=calendar.provider,
                )

                # Delete all events associated with this calendar
                event_count = events.count()
                logger.info(f"Deleting {event_count} events associated with calendar")
                events.delete()

                # Delete all related records
                DeletedExternalEvent.objects.filter(calendar=calendar).delete()
                ModifiedExternalEvent.objects.filter(calendar=calendar).delete()
                SyncLog.objects.filter(calendar=calendar).delete()

                # Delete the calendar visibility settings
                try:
                    calendar.visibility.delete()
                except CalendarVisibility.DoesNotExist:
                    pass

                # Finally delete the calendar itself
                logger.info(f"Deleting calendar {calendar.id}")
                calendar.delete()
                logger.info("Calendar deleted successfully")

            messages.success(
                request,
                f'Calendar "{account_name}" and {event_count} associated events were deleted successfully.',
            )
            return redirect("calendars:external_calendar_list")
        except Exception as e:
            logger.error(f"Error deleting calendar: {str(e)}", exc_info=True)
            messages.error(
                request,
                f"Error deleting calendar: {str(e)}",
            )
            return redirect(
                "calendars:external_calendar_detail", calendar_id=calendar_id
            )

    context = {
        "calendar": calendar,
    }

    return render(request, "calendars/external_confirm_delete.html", context)


