@login_required
def get_calendar_suggestions(request: HttpRequest) -> JsonResponse:
    """
    AJAX endpoint to fetch calendar name suggestions from an ICS URL.
    """
    if request.method == "POST":
        import json
        from urllib.parse import urlparse

        from django.core.exceptions import ValidationError
        from django.core.validators import URLValidator

        try:
            data = json.loads(request.body)
            calendar_url = (data.get("calendar_url") or "").strip()
        except (json.JSONDecodeError, AttributeError):
            calendar_url = (request.POST.get("calendar_url") or "").strip()

        if not calendar_url:
            return JsonResponse(
                {"suggestions": [], "error": "No URL provided"}, status=400
            )

        # Normalize webcal to https for validation
        normalized_url = calendar_url
        if normalized_url.lower().startswith("webcal://"):
            normalized_url = "https://" + normalized_url[9:]

        # Validate URL and scheme
        validator = URLValidator(schemes=["http", "https"])
        try:
            validator(normalized_url)
        except ValidationError:
            return JsonResponse({"suggestions": [], "error": "Invalid URL"}, status=400)

        safe_url = normalize_and_validate_ics_url(calendar_url)
        if safe_url is None:
            return JsonResponse(
                {"suggestions": [], "error": "URL not allowed"}, status=400
            )
        parsed = urlparse(safe_url)

        # Fetch metadata (with a shorter timeout for responsiveness)
        metadata = fetch_ics_metadata(safe_url, timeout=5)

        if metadata:
            suggestions = metadata.get("suggested_names", [])

            # Add the actual calendar name if available and not already in suggestions
            if (
                metadata.get("calendar_name")
                and metadata["calendar_name"] not in suggestions
            ):
                suggestions.insert(0, metadata["calendar_name"])

            # Include additional metadata for richer frontend experience
            response_data = {
                "suggestions": suggestions[:5],  # Limit to 5 suggestions
                "metadata": {
                    "calendar_name": metadata.get("calendar_name"),
                    "description": metadata.get("calendar_description"),
                    "event_count": metadata.get("event_count", 0),
                    "timezone": metadata.get("timezone"),
                },
            }

            return JsonResponse(response_data)

        # Fallback to basic URL-based suggestions
        domain = (parsed.netloc or "").lower()
        suggestions = []
        if "google.com" in domain:
            suggestions.append("Google Calendar")
        elif "outlook" in domain or "office365" in domain:
            suggestions.append("Outlook Calendar")
        elif "icloud.com" in domain:
            suggestions.append("Apple Calendar")
        else:
            # Try to extract from domain
            domain_parts = domain.split(".")
            if len(domain_parts) >= 2:
                org = domain_parts[-2]
                if org not in ["www", "calendar", "events"]:
                    suggestions.append(f"{org.title()} Calendar")

        return JsonResponse({"suggestions": suggestions, "metadata": {}})

    return JsonResponse({"error": "Invalid request method"}, status=405)

from typing import Any
import logging
from datetime import datetime, timedelta
from uuid import UUID

from django.contrib.auth.decorators import login_required
from django.contrib.auth.models import User
from django.db.models import Prefetch, Q
from django.shortcuts import render
from django.utils import timezone

from calendars.models import ExternalCalendarAccount, InternalCalendar
from events.models import Event
from events.sharing_models import TentativeEventShare
from family_scheduler.utils.observability import child_span, set_span_attributes
from users.models import FamilyGroup, MetaFamilyMembership

logger = logging.getLogger(__name__)


@login_required
def week_view(request: Any) -> Any:
    """
    Weekly view of events with advanced filtering
    """
    with child_span("web.calendars.week.load_events") as load_span:
        # Get the current date or the requested date
        year = int(request.GET.get("year", timezone.now().year))
        month = int(request.GET.get("month", timezone.now().month))
        day = int(request.GET.get("day", timezone.now().day))

        # Create date object for the requested day
        date = datetime(year, month, day)

        # Get current date and time for the "Today" highlight
        today = timezone.now()

        # Calculate the start of the week (Monday)
        # weekday() returns 0 for Monday, 6 for Sunday
        # To get Monday as start, we use weekday() directly
        days_since_monday = date.weekday()
        start_of_week = date - timedelta(days=days_since_monday)

        # Calculate the end of the week (Sunday)
        end_of_week = start_of_week + timedelta(days=6)

        # Get all family groups the user is a member of
        family_ids = list(
            request.user.family_memberships.values_list("family_id", flat=True)
        )
        family_groups = FamilyGroup.objects.filter(id__in=family_ids)

        # Get all meta family groups the user's families are members of
        meta_family_ids = list(
            MetaFamilyMembership.objects.filter(family_id__in=family_ids).values_list(
                "meta_family_id", flat=True
            )
        )

        # Get all families that are members of these meta family groups (the family network)
        network_family_ids = list(
            MetaFamilyMembership.objects.filter(meta_family_id__in=meta_family_ids)
            .values_list("family_id", flat=True)
            .distinct()
        )

        # Get user's calendars
        external_calendars = ExternalCalendarAccount.objects.filter(user=request.user)
        internal_calendars = InternalCalendar.objects.filter(
            user=request.user, is_active=True
        )

        # Get family members for filtering
        family_members = (
            User.objects.filter(family_memberships__family_id__in=family_ids)
            .distinct()
            .exclude(id=request.user.id)
        )

        # Process filter parameters
        selected_internal_calendars = []
        selected_external_calendars = []
        selected_families = []
        selected_visibilities = []
        selected_members = []
        filter_params = {}

        # Get option to include family events (legacy support, default to True)
        include_family_events = (
            request.GET.get("include_family", "true").lower() == "true"
        )

        # Process advanced filter parameters
        if "internal_calendars" in request.GET:
            selected_internal_calendars = [
                int(cal_id)
                for cal_id in request.GET.get("internal_calendars").split(",")
                if cal_id.isdigit()
            ]
            filter_params["internal_calendars"] = request.GET.get("internal_calendars")

        if "external_calendars" in request.GET:
            selected_external_calendars = [
                int(cal_id)
                for cal_id in request.GET.get("external_calendars").split(",")
                if cal_id.isdigit()
            ]
            filter_params["external_calendars"] = request.GET.get("external_calendars")

        if "families" in request.GET:
            selected_families = [
                int(fam_id)
                for fam_id in request.GET.get("families").split(",")
                if fam_id.isdigit()
            ]
            filter_params["families"] = request.GET.get("families")

        if "visibilities" in request.GET:
            selected_visibilities = request.GET.get("visibilities").split(",")
            valid_visibilities = [
                v
                for v in selected_visibilities
                if v in ["PUBLIC", "PRIVATE", "PERSONAL"]
            ]
            selected_visibilities = valid_visibilities
            filter_params["visibilities"] = request.GET.get("visibilities")

        if "members" in request.GET:
            selected_members = [
                int(mem_id)
                for mem_id in request.GET.get("members").split(",")
                if mem_id.isdigit()
            ]
            filter_params["members"] = request.GET.get("members")

        # Build the query for events
        events_query = Q()

        # Get all available calendar IDs
        all_internal_cal_ids = list(internal_calendars.values_list("id", flat=True))

        # Map external calendar account PKs to all supported event.calendar_id values
        # (account PK and provider calendar_id) to support mixed legacy/new records.
        external_cal_map: dict[int, list[str]] = {}
        all_external_calendar_values: set[str] = set()
        for cal in external_calendars:
            calendar_values = [str(cal.id)]
            if cal.calendar_id:
                calendar_values.append(cal.calendar_id)
            external_cal_map[cal.id] = calendar_values
            all_external_calendar_values.update(calendar_values)

        # Debug information
        logger.debug(
            "Week View - Selected internal calendars: %s", selected_internal_calendars
        )
        logger.debug(
            "Week View - Selected external calendars: %s", selected_external_calendars
        )
        logger.debug("Week View - External calendar map: %s", external_cal_map)

        # If no filters are selected, use the legacy include_family_events option
        # Tentative events shared with user's families
        shared_tentative_event_ids = TentativeEventShare.objects.filter(
            target_family_id__in=family_ids
        ).values_list("event_id", flat=True)
        from events.participation import confirmed_event_queryset_for_user

        confirmed_event_ids = confirmed_event_queryset_for_user(request.user).values(
            "id"
        )

        if not (
            selected_internal_calendars
            or selected_external_calendars
            or selected_families
            or selected_visibilities
            or selected_members
        ):
            if include_family_events:
                # Include family events with PUBLIC visibility (including from family network)
                events_query = (
                    Q(family_group_id__in=family_ids, visibility="PUBLIC")
                    | Q(family_group_id__in=network_family_ids, visibility="PUBLIC")
                    | Q(participants__user=request.user)
                    | Q(creator=request.user)
                    | Q(id__in=confirmed_event_ids)
                    | Q(id__in=shared_tentative_event_ids)
                )
            else:
                # Only include events where the user is a participant or creator
                events_query = (
                    Q(participants__user=request.user)
                    | Q(creator=request.user)
                    | Q(id__in=confirmed_event_ids)
                )
        else:
            # Start with an empty query - we'll build it up based on filters
            calendar_query = Q()
            user_events_query = Q(creator=request.user)

            # Calendar filtering
            if selected_internal_calendars or selected_external_calendars:
                # If specific internal calendars are selected, only include those
                if selected_internal_calendars:
                    calendar_query |= Q(
                        internal_calendar_id__in=selected_internal_calendars
                    )

                # If specific external calendars are selected, only include those
                if selected_external_calendars:
                    # Convert external calendar IDs to their actual calendar_id values
                    external_cal_ids = []
                    for cal_id in selected_external_calendars:
                        if cal_id in external_cal_map:
                            external_cal_ids.extend(external_cal_map[cal_id])

                    external_cal_ids = list(dict.fromkeys(external_cal_ids))

                    logger.debug(
                        "Week View - Mapped external calendar IDs: %s", external_cal_ids
                    )
                    if external_cal_ids:
                        calendar_query |= Q(
                            is_external=True, calendar_id__in=external_cal_ids
                        )

                # If calendar filters were provided but none resolve to accessible calendars,
                # force an empty result instead of falling back to an unfiltered query.
                if calendar_query == Q():
                    calendar_query = Q(pk__in=[])
            else:
                # If no calendars are explicitly selected, include all calendars
                calendar_query |= Q(internal_calendar_id__in=all_internal_cal_ids)
                calendar_query |= Q(
                    is_external=True,
                    calendar_id__in=list(all_external_calendar_values),
                )

            # Apply calendar filter
            events_query = calendar_query

            # Filter by families
            if selected_families:
                family_query = Q(family_group_id__in=selected_families)
                events_query &= family_query

            # Filter by visibility
            if selected_visibilities:
                visibility_query = Q(visibility__in=selected_visibilities)
                events_query &= visibility_query

            # Filter by family members (participants)
            if selected_members:
                member_query = Q(participants__user_id__in=selected_members)
                events_query &= member_query

            # Include user's events only if they match the calendar filter
            # This ensures that user's events from disabled calendars don't show up
            events_query |= user_events_query & calendar_query

        # Get events for the week
        events = list(
            Event.objects.filter(
                events_query,
                start_time__gte=start_of_week,
                start_time__lte=end_of_week.replace(hour=23, minute=59, second=59),
            )
            .distinct()
            .order_by("start_time")
            .select_related("creator", "creator__profile", "internal_calendar")
            .prefetch_related("participants")
        )
        set_span_attributes(
            load_span,
            event_count=len(events),
            family_count=len(family_ids),
            network_family_count=len(network_family_ids),
            internal_calendar_filter_count=len(selected_internal_calendars),
            external_calendar_filter_count=len(selected_external_calendars),
            family_filter_count=len(selected_families),
            member_filter_count=len(selected_members),
            has_visibility_filter=bool(selected_visibilities),
        )

    # --- Fetch associated child info ---
    with child_span(
        "web.calendars.week.build_child_info",
        event_count=len(events),
    ) as child_info_span:
        child_info_by_calendar: dict[
            UUID | str, dict[str, str]
        ] = {}  # Maps calendar identifier to child info

        # Process internal calendars
        internal_calendar_ids_for_events = {
            e.internal_calendar_id for e in events if e.internal_calendar_id
        }
        if internal_calendar_ids_for_events:
            internal_calendars_with_children = InternalCalendar.objects.filter(
                id__in=internal_calendar_ids_for_events
            ).prefetch_related("associated_children")
            for cal in internal_calendars_with_children:
                for child in cal.associated_children.all():
                    if child.profile_picture:
                        child_info_by_calendar[cal.id] = {
                            "name": child.get_full_name(),
                            "picture_url": child.profile_picture.url,
                        }
                        break

        # Process external calendars
        external_calendar_sources_for_events = {
            str(e.calendar_id) for e in events if e.is_external and e.calendar_id
        }
        if external_calendar_sources_for_events:
            external_calendar_account_ids_for_events = [
                int(source)
                for source in external_calendar_sources_for_events
                if source.isdigit()
            ]
            external_calendar_query = Q(
                calendar_id__in=external_calendar_sources_for_events
            )
            if external_calendar_account_ids_for_events:
                external_calendar_query |= Q(
                    id__in=external_calendar_account_ids_for_events
                )

            external_calendars_with_children = ExternalCalendarAccount.objects.filter(
                external_calendar_query
            ).prefetch_related("associated_children")
            for cal in external_calendars_with_children:
                for child in cal.associated_children.all():
                    if child.profile_picture:
                        child_info = {
                            "name": child.get_full_name(),
                            "picture_url": child.profile_picture.url,
                        }
                        if cal.calendar_id:
                            child_info_by_calendar[cal.calendar_id] = child_info
                        child_info_by_calendar[str(cal.id)] = child_info
                        break

        # Map event IDs to child info
        event_child_info = {}
        for event in events:
            calendar_key: UUID | str | None = None
            if event.internal_calendar_id:
                calendar_key = event.internal_calendar_id
            elif event.is_external and event.calendar_id:
                calendar_key = event.calendar_id

            if calendar_key and calendar_key in child_info_by_calendar:
                event_child_info[event.id] = child_info_by_calendar[calendar_key]
        set_span_attributes(
            child_info_span,
            child_info_count=len(event_child_info),
            internal_calendar_count=len(internal_calendar_ids_for_events),
            external_calendar_count=len(external_calendar_sources_for_events),
        )
    # --- End Fetch associated child info ---

    # Organize events by day
    days = []
    events_by_day: dict[int, list[Event]] = {}

    for i in range(7):
        day_date = start_of_week + timedelta(days=i)
        days.append(day_date)
        events_by_day[i] = []

    for event in events:
        day_index = (event.start_time.date() - start_of_week.date()).days
        if 0 <= day_index <= 6:
            events_by_day[day_index].append(event)

    with child_span(
        "web.calendars.week.build_event_calendar_info",
        event_count=len(events),
    ) as calendar_info_span:
        # Create dictionaries to store calendar information
        event_calendar_info = {}
        internal_calendar_colors = {}
        calendar_user_prefetch = Prefetch(
            "associated_users",
            queryset=User.objects.select_related("profile"),
        )

        # Get internal calendar information WITH associated_users
        internal_calendar_ids = [
            e.internal_calendar_id for e in events if e.internal_calendar_id
        ]
        internal_calendars_dict = {}
        if internal_calendar_ids:
            internal_calendars_list = (
                InternalCalendar.objects.filter(id__in=internal_calendar_ids)
                .select_related("user__profile")
                .prefetch_related(calendar_user_prefetch, "associated_children")
            )
            internal_calendars_dict = {
                calendar_obj.id: calendar_obj
                for calendar_obj in internal_calendars_list
            }

            # Store colors for internal calendars
            for calendar_obj in internal_calendars_list:
                internal_calendar_colors[calendar_obj.id] = calendar_obj.color

        # Get external calendar information WITH associated_users
        external_sources = {
            str(e.calendar_id) for e in events if e.is_external and e.calendar_id
        }
        external_calendars_dict = {}
        if external_sources:
            external_calendar_account_ids = [
                int(source) for source in external_sources if source.isdigit()
            ]
            external_calendars_query = Q(calendar_id__in=external_sources)
            if external_calendar_account_ids:
                external_calendars_query |= Q(id__in=external_calendar_account_ids)

            external_calendars_list = (
                ExternalCalendarAccount.objects.filter(external_calendars_query)
                .select_related("user__profile")
                .prefetch_related(calendar_user_prefetch, "associated_children")
            )
            for calendar_obj in external_calendars_list:
                if calendar_obj.calendar_id:
                    external_calendars_dict[calendar_obj.calendar_id] = calendar_obj
                external_calendars_dict[str(calendar_obj.id)] = calendar_obj

        # Associate calendar information with each event INCLUDING associated_users
        for event in events:
            if (
                event.internal_calendar_id
                and event.internal_calendar_id in internal_calendars_dict
            ):
                calendar_obj = internal_calendars_dict[event.internal_calendar_id]
                event_calendar_info[str(event.id)] = {
                    "type": calendar_obj.type,
                    "sports_subcategory": calendar_obj.sports_subcategory,
                    "is_internal": True,
                    "associated_users": list(calendar_obj.associated_users.all()),
                }
            elif (
                event.is_external
                and event.calendar_id
                and str(event.calendar_id) in external_calendars_dict
            ):
                calendar_obj = external_calendars_dict[str(event.calendar_id)]
