    permission_classes = [IsAuthenticated, IsHouseholdFamilyMember]
    serializer_class = HouseholdProjectMilestoneSerializer

    def get_queryset(self) -> Any:
        """Return milestones for projects the user has access to."""
        user = self.request.user
        family_ids = FamilyMembership.objects.filter(user=user).values_list(  # type: ignore[misc]
            "family_id", flat=True
        )

        project_id = self.kwargs.get("project_pk")

        return HouseholdProjectMilestone.objects.filter(
            project_id=project_id,
            project__household__family_id__in=family_ids,
        ).order_by("sort_order", "target_date")

    def perform_create(self, serializer: Any) -> Any:
        """Create a new milestone."""
        project_id = self.kwargs.get("project_pk")
        try:
            project = HouseholdProject.objects.select_related("household").get(  # type: ignore[misc]
                id=project_id
            )
        except HouseholdProject.DoesNotExist as e:
            logger.error("Project not found: %s", project_id)
            raise ValidationError("Project not found") from e

        # SECURITY: re-validate family membership at create time.
        family_ids = FamilyMembership.objects.filter(  # type: ignore[misc]
            user=self.request.user, is_active=True
        ).values_list("family_id", flat=True)
        if project.household.family_id not in family_ids:
            logger.warning(
                "User %s blocked from creating milestone on project %s",
                self.request.user.id,
                project_id,
            )
            raise PermissionDenied("You do not have access to this project")

        # Auto-assign sort_order if not provided
        if "sort_order" not in serializer.validated_data:
            max_order = (
                HouseholdProjectMilestone.objects.filter(project=project).aggregate(
                    max_order=models.Max("sort_order")
                )["max_order"]
                or 0
            )
            serializer.validated_data["sort_order"] = max_order + 1

        serializer.save(project=project)

        logger.info(
            "Milestone created for project %s by user %s",
            project_id,
            self.request.user.id,
        )
        record_wide_event(
            request=self.request,
            operation="project_milestone.create",
            outcome="success",
        )
