class HouseholdViewSet(FeatureRequiredMixin, viewsets.ModelViewSet[Household]):
    """ViewSet for Household model."""

    required_feature = "households"

    permission_classes = [IsAuthenticated, IsHouseholdFamilyMember]
    pagination_class = HouseholdPageNumberPagination

    def get_queryset(self) -> Any:
        """
        Return households for families that the user is a member of.
        """
        user = self.request.user
        family_ids = FamilyMembership.objects.filter(user=user).values_list(  # type: ignore[misc]
            "family_id", flat=True
        )

        # Annotate with counts to avoid N+1 queries when serializing
        return (
            Household.objects.filter(family_id__in=family_ids, is_active=True)
            .select_related("family", "created_by")
            .prefetch_related("appliances", "maintenance_tasks")
            .annotate(
                appliance_count=models.Count(
                    "appliances",
                    filter=models.Q(appliances__is_active=True),
                    distinct=True,
                ),
                maintenance_tasks_count=models.Count(
                    "maintenance_tasks",
                    filter=models.Q(maintenance_tasks__is_active=True),
                    distinct=True,
                ),
            )
            .order_by("-is_primary", "name")
        )

    def get_serializer_class(self) -> Any:
        """Return appropriate serializer class based on the action."""
        if self.action == "list":
            return HouseholdListSerializer
        elif self.action in ["create", "update", "partial_update"]:
            return HouseholdCreateUpdateSerializer
        return HouseholdDetailSerializer

    def perform_create(self, serializer: Any) -> Any:
        """Create a new household."""
        try:
            with transaction.atomic():
                # Get the user's primary family
                family_membership = FamilyMembership.objects.filter(
                    user=self.request.user  # type: ignore[misc]
                ).first()

                if not family_membership:
                    raise ValidationError(
                        {
                            "detail": "You must be a member of a family to create households"
                        }
                    )

                household = HouseholdService.create_household(
                    family=family_membership.family,
                    created_by=self.request.user,
                    **serializer.validated_data,
                )

                serializer.instance = household

        except ValidationError as e:
            logger.warning("Validation error creating household: %s", str(e))
            raise
        except Exception as e:
            logger.error("Error creating household: %s", str(e), exc_info=True)
            raise ValidationError(
                {"detail": "Failed to create household. Please try again."}
            ) from None
        record_wide_event(
            request=self.request,
            operation="household.create",
            outcome="success",
        )

    @action(detail=True, methods=["post"])
    def set_primary(self, request: Request, pk: str | None = None) -> Response:
        """Set this household as the primary household for the family."""
        household = self.get_object()

        try:
            HouseholdService.set_primary_household(household)
            serializer = self.get_serializer(household)
            return Response(serializer.data)
        except Exception as e:
            logger.error(
                "Error setting primary household %s: %s",
                household.id,
                str(e),
                exc_info=True,
            )
            return Response(
                {"error": "Failed to set primary household"},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

    @action(detail=True, methods=["post"])
    def upload_photo(self, request: Request, pk: str | None = None) -> Response:
        """
        Upload a photo for the household.

        Expects: {"photo_url": "https://s3.amazonaws.com/..."}
        """
        household = self.get_object()
        photo_url = request.data.get("photo_url")

        if not photo_url:
            return Response(
                {"error": "photo_url is required"}, status=status.HTTP_400_BAD_REQUEST
            )

        try:
            household.photo_url = photo_url
            household.save()
            serializer = self.get_serializer(household)
            return Response(serializer.data)
        except Exception as e:
            logger.error(
                "Error uploading photo for household %s: %s",
                household.id,
                str(e),
                exc_info=True,
            )
            return Response(
                {"error": "Failed to upload photo"},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

    def perform_destroy(self, instance: Any) -> None:
        """Soft delete the household by setting is_active to False."""
        instance.is_active = False
        instance.save()
        record_wide_event(
            request=self.request,
            operation="household.destroy",
            outcome="success",
        )


class ApplianceViewSet(FeatureRequiredMixin, viewsets.ModelViewSet[Appliance]):
    required_feature = "households"

    """ViewSet for Appliance model."""

    permission_classes = [IsAuthenticated, IsHouseholdFamilyMember]
    pagination_class = HouseholdPageNumberPagination

    def get_queryset(self) -> Any:
        """Return appliances for households the user has access to."""
        user = self.request.user
        family_ids = FamilyMembership.objects.filter(user=user).values_list(  # type: ignore[misc]
            "family_id", flat=True
        )

        queryset = (
            Appliance.objects.filter(
                household__family_id__in=family_ids, is_active=True
            )
            .select_related("household", "created_by")
            .order_by("household", "category", "name")
        )
        if self.action == "list":
            queryset = queryset.prefetch_related("photos")
        return queryset

    def get_serializer_class(self) -> Any:
        """Return appropriate serializer class based on the action."""
        if self.action == "list":
            return ApplianceListSerializer
        elif self.action in ["create", "update", "partial_update"]:
            return ApplianceCreateUpdateSerializer
        return ApplianceDetailSerializer

    def create(self, request: Request, *args: Any, **kwargs: Any) -> Response:
        """Create a new appliance and return detail serializer response."""
        serializer = self.get_serializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        self.perform_create(serializer)

        # Use detail serializer for response to include all fields
        response_serializer = ApplianceDetailSerializer(
            serializer.instance, context=self.get_serializer_context()
        )
        headers = self.get_success_headers(response_serializer.data)
        record_wide_event(
            request=request,
            operation="appliance.create",
            outcome="success",
            appliance_id=str(serializer.instance.id) if serializer.instance else "",
        )
        return Response(
            response_serializer.data, status=status.HTTP_201_CREATED, headers=headers
        )

    def perform_create(self, serializer: Any) -> Any:
        """Create a new appliance."""
        try:
            with transaction.atomic():
                # Get household from validated data
                validated_data = serializer.validated_data.copy()
                household_id = validated_data.pop("household", None)

                if not household_id:
                    raise ValidationError({"household": "This field is required"})

                household = Household.objects.get(id=household_id)

                # Verify user has access to this household
                if not FamilyMembership.objects.filter(
                    user=self.request.user,
                    family=household.family,  # type: ignore[misc]
                ).exists():
                    raise ValidationError(
                        {"detail": "You do not have access to this household"}
                    )

                appliance = ApplianceService.create_appliance(
                    household=household,
                    created_by=self.request.user,
                    **validated_data,
                )

                serializer.instance = appliance

        except ValidationError as e:
            logger.warning("Validation error creating appliance: %s", str(e))
            raise
        except Exception as e:
            logger.error("Error creating appliance: %s", str(e), exc_info=True)
            raise ValidationError(
                {"detail": "Failed to create appliance. Please try again."}
            ) from None
        record_wide_event(
            request=self.request,
            operation="appliance.create",
            outcome="success",
            appliance_id=str(serializer.instance.id),
        )

    def update(self, request: Request, *args: Any, **kwargs: Any) -> Response:
        """Update an appliance and return detail serializer response."""
        partial = kwargs.pop("partial", False)
        instance = self.get_object()
        serializer = self.get_serializer(instance, data=request.data, partial=partial)
        serializer.is_valid(raise_exception=True)
        self.perform_update(serializer)

        record_wide_event(
            request=self.request,
            operation="appliance.update",
            outcome="success",
        )

        response_serializer = ApplianceDetailSerializer(
            serializer.instance, context=self.get_serializer_context()
        )
        return Response(response_serializer.data)

    @action(detail=False, methods=["get"])
    def expiring_warranties(self, request: Any) -> Any:
        """
        Get appliances with warranties expiring soon.

        Query params:
        - household: Household ID (required)
        - days: Number of days to look ahead (default: 30)
        """
        household_id = request.query_params.get("household")
        days = int(request.query_params.get("days", 30))

        if not household_id:
            return Response(
                {"error": "household parameter is required"},
                status=status.HTTP_400_BAD_REQUEST,
            )

        try:
            household = Household.objects.get(id=household_id)

            # Verify user has access
            if not FamilyMembership.objects.filter(
                user=request.user, family=household.family
            ).exists():
                return Response(
                    {"error": "You do not have access to this household"},
                    status=status.HTTP_403_FORBIDDEN,
                )

            appliances = ApplianceService.get_expiring_warranties(household, days=days)
            serializer = ApplianceListSerializer(appliances, many=True)
            return Response(serializer.data)

        except Household.DoesNotExist:
            return Response(
                {"error": "Household not found"}, status=status.HTTP_404_NOT_FOUND
            )
        except Exception as e:
            logger.error(
                "Error fetching expiring warranties: %s", str(e), exc_info=True
            )
            return Response(
                {"error": "Failed to fetch expiring warranties"},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

    @action(detail=True, methods=["post"])
