        """
        appliance = self.get_object()
        photo_url = request.data.get("photo_url")

        if not photo_url:
            return Response(
                {"error": "photo_url is required"}, status=status.HTTP_400_BAD_REQUEST
            )

        try:
            with transaction.atomic():
                # Use get_or_create to prevent race conditions
                photo, _ = AppliancePhoto.objects.get_or_create(
