                )

            # Refresh to get updated state
            appliance.refresh_from_db()
            serializer = self.get_serializer(appliance)
            return Response(serializer.data)
        except Exception as e:
            logger.error(
                "Error uploading photo for appliance %s: %s",
                appliance.id,
                str(e),
                exc_info=True,
            )
            return Response(
                {"error": "Failed to upload photo"},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

    @action(detail=False, methods=["post"], throttle_classes=[AIVisionThrottle])
    def parse_photo(self, request: Any) -> Any:
        """
        Parse appliance information from a photo.

        Rate limited to 10 requests per hour per user due to AI API costs.

        Expects:
        {
            "photo_url": "https://s3.amazonaws.com/...",
            "household_id": "uuid-string"  # optional, for validation
        }

        Returns:
        {
            "success": true,
            "data": {
                "manufacturer": "Samsung",
                "model_number": "RF28R7351SR",
                "serial_number": "SN123456789",
                "model_name": "French Door Refrigerator",
                "confidence": {
                    "manufacturer": 0.95,
                    "model_number": 0.90,
                    "serial_number": 0.85,
                    "model_name": 0.80
                },
                "processing_notes": "Clear image, all fields extracted successfully",
                "raw_text": "SAMSUNG Model RF28R7351SR Serial SN123456789..."
            }
        }
        """
        photo_url = request.data.get("photo_url")
        household_id = request.data.get("household_id")

        if not photo_url:
            return Response(
                {"error": "photo_url is required"},
                status=status.HTTP_400_BAD_REQUEST,
            )

        # SECURITY: Require household_id for authorization validation
        if not household_id:
            return Response(
                {"error": "household_id is required for security validation"},
                status=status.HTTP_400_BAD_REQUEST,
            )

        # Validate household access
        try:
            household = Household.objects.get(id=household_id)
            if not FamilyMembership.objects.filter(
                user=request.user, family=household.family
            ).exists():
                return Response(
                    {"error": "You do not have access to this household"},
                    status=status.HTTP_403_FORBIDDEN,
                )
        except Household.DoesNotExist:
            return Response(
                {"error": "Household not found"},
                status=status.HTTP_404_NOT_FOUND,
            )

        try:
            result = ApplianceVisionService.process_appliance_photo(photo_url)

            if result["success"]:
                return Response(result, status=status.HTTP_200_OK)
            else:
                return Response(
                    {"error": result.get("error", "Processing failed")},
